// Adapta el payload del formulario externo (diseño de Asesor CCB, Vercel, solo Info. Georreferenciada)
// al contrato plano que ya consume el sub-workflow 'Guardar Criterios y Cotizar Servicio',
// replicando exactamente lo que 'Consolidar criterios - Información Georreferenciada' (W2)
// produce hoy -- así se reutiliza el motor (W3) sin tocarlo.

const b = $json.body || $json;

const join = (arr) => Array.isArray(arr) ? arr.filter(Boolean).join('; ') : (arr || '');
const num = (v) => (v === '' || v === undefined || v === null) ? null : Number(v);
// El motor solo reconoce 'Personas Jurídicas' / 'Personas Naturales' exactos para mapear al
// valor de la BD (TIPO_FORM_TO_BD); el form de Asesor CCB agrega sufijos aclaratorios que hay que
// quitar acá para que el match no falle en silencio (bug detectado en prueba en vivo).
const limpiarOrganizacion = (v) => String(v).replace(/\s*\(sociedades\)\s*/i, '').trim();

// --- Ubicación: mapeo explícito a las claves que reconoce el motor (Normalizar Criterios, W3) ---
// 'Barranquilla' y 'Todo el Departamento del Atlántico' ya matchean tal cual tras normalize().
// 'Área Metropolitana...' del form es un texto largo con paréntesis -- se normaliza acá a la
// forma corta que sí matchea la categoría del motor. Las otras 2 opciones caen al camino de
// lista literal de municipios (también soportado por el motor sin cambios).
let ubicacionGeografica = '';
const ubic = b.ubicacion || '';
if (ubic === 'Barranquilla') {
  ubicacionGeografica = 'Barranquilla';
} else if (ubic.startsWith('Área Metropolitana')) {
  ubicacionGeografica = 'Área Metropolitana de Barranquilla';
} else if (ubic === 'Todo el Departamento del Atlántico') {
  ubicacionGeografica = 'Todo el Departamento del Atlántico';
} else if (ubic.startsWith('Ciudades')) {
  ubicacionGeografica = b.municipios || '';
} else if (ubic.startsWith('Municipios del Magdalena')) {
  ubicacionGeografica = join(b.municipios_magdalena);
}

// --- Actividad económica: 'todas' o lista de sectores seleccionados ---
const actividadEconomica = b.todas_actividades ? 'Todas las actividades económicas' : join(b.sectores);

// --- Activos: modo (ninguno/mayor/menor/entre) -> columnas min/max/entre/y ---
const activos = b.activos || {};
let activos_min = null, activos_max = null, activos_entre = null, activos_y = null;
if (activos.modo === 'mayor') activos_min = num(activos.desde);
else if (activos.modo === 'menor') activos_max = num(activos.desde);
else if (activos.modo === 'entre') { activos_entre = num(activos.desde); activos_y = num(activos.hasta); }

// --- Ventas: modo (indiferente/mayor/menor/entre) -> columnas + indiferente_ventas ---
const ventas = b.ventas || {};
let ventas_min = null, ventas_max = null, ventas_entre = null, ventas_y = null;
const indiferenteVentas = ventas.modo === 'indiferente' || !ventas.modo;
if (ventas.modo === 'mayor') ventas_min = num(ventas.desde);
else if (ventas.modo === 'menor') ventas_max = num(ventas.desde);
else if (ventas.modo === 'entre') { ventas_entre = num(ventas.desde); ventas_y = num(ventas.hasta); }

// Este formulario se abre directo (sin pasar por W1/el link con ?id_solicitud=),
// asi que si llega vacio generamos uno propio, mismo patron que usa W1.
const idSolicitud = b.id_solicitud || ('SOL-' + DateTime.now().setZone('America/Bogota').toFormat('yyyyMMddHHmmss'));

const criterios = {
  id_solicitud: idSolicitud,
  razon_social: b.razon_social || '',
  nit_cc: '', direccion_empresa: '', email_empresa: '', telefono_empresa: '', ciudad: '',
  nombre_solicitante: b.nombre || '',
  cc_solicitante: '',
  telefono_solicitante: b.telefono || '',
  direccion_solicitante: '',
  representacion_empresa: '', empresa_representada: '',
  email_solicitante: b.email || '',
  cargo: '', nivel_cargo: '', area_cargo: '',
  servicio: 'Información Georreferenciada',
  organizacion_juridica: Array.isArray(b.organizacion_juridica) ? b.organizacion_juridica.map(limpiarOrganizacion).join('; ') : limpiarOrganizacion(b.organizacion_juridica || ''),
  ubicacion_geografica: ubicacionGeografica,
  ciudades_municipios: b.municipios || '',
  actividad_economica: actividadEconomica,
  actividades_especificas: b.actividades_especificas || '',
  categorias_esal: join(b.esal),
  categorias_esal_especificas: b.esal_especificas || '',
  tamano_empresa: join(b.tamanos),
  activos_min: activos_min, activos_max: activos_max, activos_entre: activos_entre, activos_y: activos_y,
  ventas_min: ventas_min, ventas_max: ventas_max, ventas_entre: ventas_entre, ventas_y: ventas_y,
  indiferente_ventas: indiferenteVentas,
  medio_conocimiento: join(b.como_nos_conocio),
  otro_medio: b.como_nos_conocio_otro || '',
  comentarios: b.comentarios || '',
  fecha_envio: DateTime.now().setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss')
};

return { json: criterios };

const b = $json.body || $json;
const requeridos = ['nombre', 'email', 'telefono', 'razon_social'];
const faltantes = requeridos.filter((campo) => !b[campo] || String(b[campo]).trim() === '');
return { json: { ...$json, valido: faltantes.length === 0, campos_faltantes: faltantes } };

const j = $json;
const b = j.body || j;
const mensaje = 'Faltan campos requeridos en la solicitud: ' + (j.campos_faltantes || []).join(', ');
return { json: {
  id_solicitud: b.id_solicitud || '',
  workflow_origen: 'W2C-recepcion-formulario-externo',
  nodo_fallido: 'Validar campos requeridos',
  mensaje_error: mensaje,
  ok: false,
  error: mensaje
} };
